style.css:
:root {
  --claude-bg: #FAF9F5;
  --claude-text: #1F1E1D;
  --claude-accent: #C96442;
}

@media (prefers-color-scheme: dark) {
  :root {
    --claude-bg: #191919;
    --claude-text: #F5E6D3;
    --claude-accent: #E07A47;
  }
}


body, main, div, section, article {
  background-color: var(--claude-bg) !important;
  color: var(--claude-text) !important;
}


a {
  color: var(--claude-accent) !important;
}
